import {icon,esc,state,fresh,save,day,courses,course,setCourses,toast,go,empty,btn,modal,closeModal,storedCourses,putCourse,deleteCourse} from './core.js';
const modalHead=t=>`<div class="modal-header"><h2 id="modal-title">${esc(t)}</h2><button class="icon-button" data-action="close-modal" aria-label="ปิด">${icon('x')}</button></div>`;
export function openUpload(){modal(modalHead('เพิ่มสไลด์ของคุณ')+`<p>เก็บเอกสารอ้างอิงไว้ในเบราว์เซอร์ของคุณ เพื่อเตรียมบทเรียนเพิ่มเติม ไฟล์ไม่ถูกส่งขึ้นเว็บ</p><label>ชื่อบทเรียน<input id="upload-title" maxlength="100" placeholder="เช่น บทที่ 9 · Operating Systems"></label><label>วิชา<input id="upload-subject" maxlength="100" value="Computer Architecture"></label><div class="drop-zone" id="drop-zone">${icon('upload')}<p>เลือกไฟล์ หรือวางไฟล์ที่นี่</p><small>PDF หรือ PowerPoint (.pptx) · ไม่เกิน 25 MB</small><input id="upload-file" type="file" accept=".pdf,.pptx" aria-label="เลือกไฟล์สไลด์"></div><div class="notice">บทสอนในคลังเรียบเรียงใหม่ตามแต่ละหน้า ไม่มีการฝัง PDF หรือภาพสไลด์ต้นฉบับ<br><br>เอกสารที่เพิ่มเองเก็บเป็นไฟล์อ้างอิงส่วนตัวเท่านั้น ยังไม่สร้างคำสอนหรือข้อสอบให้อัตโนมัติ ต้องเตรียมบทสอนเพิ่มเติมก่อน</div><div id="upload-status" aria-live="polite"></div><div class="modal-footer">${btn('ยกเลิก','data-action="close-modal"','ghost')}${btn(icon('plus')+'เพิ่มในคลัง','data-action="confirm-upload"','primary')}</div>`);const dz=document.getElementById('drop-zone');dz.addEventListener('dragover',e=>{e.preventDefault();dz.style.borderColor='var(--accent)';});dz.addEventListener('dragleave',()=>dz.style.borderColor='');dz.addEventListener('drop',e=>{e.preventDefault();dz.style.borderColor='';const input=document.getElementById('upload-file');if(e.dataTransfer.files.length)input.files=e.dataTransfer.files;});document.getElementById('upload-file').addEventListener('change',e=>{const input=document.getElementById('upload-title');if(!input.value&&e.target.files[0])input.value=e.target.files[0].name.replace(/\.(pdf|pptx)$/i,'');});}
function parseXML(text){const d=new DOMParser().parseFromString(text,'application/xml');if(d.querySelector('parsererror'))throw Error('อ่านโครงสร้าง PowerPoint ไม่ได้');return d;}
async function parsePptx(file,update){const zip=await window.JSZip.loadAsync(file);const expanded=Object.values(zip.files).reduce((s,f)=>s+(f._data?.uncompressedSize||0),0);if(expanded>160*1024*1024)throw Error('ไฟล์นี้มีข้อมูลภายในมากเกินไป กรุณาบันทึกเป็น PDF');let files;const pres=zip.file('ppt/presentation.xml'),rels=zip.file('ppt/_rels/presentation.xml.rels');if(pres&&rels){const pd=parseXML(await pres.async('string')),rd=parseXML(await rels.async('string'));const map=Object.fromEntries([...rd.getElementsByTagNameNS('*','Relationship')].map(x=>[x.getAttribute('Id'),x.getAttribute('Target')]));files=[...pd.getElementsByTagNameNS('*','sldId')].map(x=>{const rid=x.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||x.getAttribute('r:id');const target=map[rid];return target?.startsWith('/')?target.slice(1):'ppt/'+target;}).filter(Boolean);}else files=Object.keys(zip.files).filter(f=>/^ppt\/slides\/slide\d+\.xml$/.test(f)).sort((a,b)=>Number(a.match(/slide(\d+)/)[1])-Number(b.match(/slide(\d+)/)[1]));if(!files.length)throw Error('ไม่พบสไลด์ในไฟล์นี้');if(files.length>500)throw Error('รองรับไม่เกิน 500 สไลด์ต่อไฟล์ กรุณาแยกไฟล์');const pages=[];for(let i=0;i<files.length;i++){const f=zip.file(files[i]);if(!f)throw Error('ไฟล์สไลด์ไม่ครบ กรุณาบันทึกไฟล์ใหม่');const doc=parseXML(await f.async('string'));const text=[...doc.getElementsByTagNameNS('*','p')].map(p=>[...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')).filter(Boolean).join('\n');pages.push({number:i+1,title:(text.split('\n')[0]||'สไลด์ '+(i+1)).slice(0,120),text});update(i+1,files.length);}return pages;}
async function importFile(){const f=document.getElementById('upload-file')?.files[0],status=document.getElementById('upload-status'),b=document.querySelector('[data-action="confirm-upload"]');if(!f){status.innerHTML='<p class="error">กรุณาเลือกไฟล์ก่อน</p>';return;}if(f.size>25*1024*1024){status.innerHTML='<p class="error">ไฟล์ใหญ่เกิน 25 MB กรุณาแบ่งไฟล์ก่อน</p>';return;}const type=f.name.toLowerCase().endsWith('.pdf')?'pdf':f.name.toLowerCase().endsWith('.pptx')?'pptx':null;if(!type){status.innerHTML='<p class="error">รองรับเฉพาะไฟล์ .pdf และ .pptx</p>';return;}b.disabled=true;const title=document.getElementById('upload-title').value.trim()||f.name.replace(/\.[^.]+$/,''),subject=document.getElementById('upload-subject').value.trim()||'วิชาของฉัน';const update=(i,n)=>{status.innerHTML=`<p class="loading-indicator">กำลังอ่านสไลด์ ${i}/${n}…</p>`;};try{let pages;if(type==='pdf'){status.innerHTML='<p class="loading-indicator">กำลังเปิดไฟล์…</p>';const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;const doc=await pdfjs.getDocument({data:new Uint8Array(await f.arrayBuffer()),isEvalSupported:false}).promise;try{if(doc.numPages>500)throw Error('รองรับไม่เกิน 500 สไลด์ต่อไฟล์ กรุณาแยกไฟล์');pages=[];for(let i=1;i<=doc.numPages;i++){const p=await doc.getPage(i),data=await p.getTextContent();const text=data.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('').trim();pages.push({number:i,title:(text.split('\n')[0]||'สไลด์ '+i).slice(0,120),text});update(i,doc.numPages);}}finally{await doc.destroy();}}else pages=await parsePptx(f,update);const c={id:'upload-'+crypto.randomUUID(),n:0,title,thai:subject,desc:'สไลด์ของคุณ',icon:'file',color:'purple',custom:true,type,fileBlob:f,pages,topics:[],questions:[],added:new Date().toISOString()};await putCourse(c);courses.push(c);closeModal();go('#folder/itds-211');toast('เพิ่มสไลด์ '+pages.length+' หน้าแล้ว');}catch(e){status.innerHTML=`<p class="error">${esc(e.message?.includes('password')?'ไฟล์มีรหัสผ่าน กรุณาใช้ไฟล์ที่เปิดอ่านได้โดยไม่ต้องใส่รหัส':e.message||'นำเข้าไฟล์ไม่สำเร็จ')}</p>`;b.disabled=false;}}
export function openSettings(goalOnly=false){modal(modalHead(goalOnly?'เป้าหมายการเรียน':'ตั้งค่าพื้นที่เรียน')+`<p>ความก้าวหน้า โน้ต และไฟล์ที่เพิ่มเองเก็บอยู่ในเบราว์เซอร์นี้ สำรองข้อมูลก่อนเปลี่ยนเครื่องหรือล้างข้อมูลเว็บไซต์</p><label>เป้าหมายประจำวัน<select id="daily-goal">${[10,15,20,30,45,60].map(v=>`<option value="${v}" ${state.goal===v?'selected':''}>${v} นาที / วัน</option>`).join('')}</select></label>${goalOnly?'':`<div class="settings-row"><div><strong>สำรองข้อมูลทั้งหมด</strong><small>รวมความก้าวหน้า โน้ต ผลสอบ และไฟล์ที่เพิ่มเอง</small></div>${btn(icon('download')+'ส่งออก','data-action="export"','small')}</div><div class="settings-row"><div><strong>กู้คืนข้อมูลสำรอง</strong><small>เลือกไฟล์สำรองจาก Try-Studying</small></div>${btn(icon('upload')+'นำเข้า','data-action="import"','small')}<input id="backup-input" type="file" accept=".json" style="display:none"></div>${courses.some(c=>c.custom)?`<div class="section-gap"><h3 style="font-size:12px;font-weight:500">ไฟล์ที่คุณเพิ่มเอง</h3>${courses.filter(c=>c.custom).map(c=>`<div class="settings-row"><strong>${esc(c.title)}</strong><button class="icon-button" data-delete-course="${c.id}" aria-label="ลบไฟล์ ${esc(c.title)}">${icon('trash')}</button></div>`).join('')}</div>`:''}<div class="settings-row"><div><strong>เริ่มบันทึกความก้าวหน้าใหม่</strong><small>ล้างคะแนน โน้ต และความก้าวหน้า เก็บไฟล์ไว้</small></div>${btn('ล้างข้อมูล','data-action="reset"','small ghost')}</div>`}<div id="settings-status" aria-live="polite"></div><div class="modal-footer">${btn('บันทึก','data-action="save-settings"','primary')}</div>`);document.getElementById('backup-input')?.addEventListener('change',e=>restoreBackup(e.target.files[0]));}
async function blobBase64(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=()=>rej(r.error);r.readAsDataURL(blob);});}
async function exportBackup(b){const old=b.innerHTML;b.disabled=true;b.textContent='กำลังสำรอง…';try{const custom=await storedCourses();const files=[];for(const c of custom){const {fileBlob,...meta}=c;files.push({...meta,fileBase64:await blobBase64(fileBlob),mime:fileBlob.type});}const backup={app:'try-study',version:1,exported:new Date().toISOString(),state,files};const blob=new Blob([JSON.stringify(backup)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Try-Studying-backup-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('ส่งออกข้อมูลสำรองแล้ว');}catch(e){toast('สำรองไม่สำเร็จ: '+e.message);}finally{b.disabled=false;b.innerHTML=old;}}
function validateState(s){if(!s||typeof s!=='object')return false;for(const f of ['read','resume','notes','drafts','mistakes','activity'])if(!s[f]||typeof s[f]!=='object'||Array.isArray(s[f]))return false;if(!Array.isArray(s.attempts)||!Array.isArray(s.bookmarks))return false;if(Object.values(s.read).some(v=>!Array.isArray(v)||v.some(x=>!Number.isInteger(x)||x<1)))return false;if(Object.values(s.notes).some(v=>typeof v!=='string'))return false;if(s.attempts.some(a=>!a||!Array.isArray(a.questions)||typeof a.answers!=='object'||!Number.isFinite(a.score)||!a.total))return false;return true;}
async function restoreBackup(f){if(!f)return;const status=document.getElementById('settings-status');try{if(f.size>150*1024*1024)throw Error('ไฟล์สำรองใหญ่เกิน 150 MB');const backup=JSON.parse(await f.text());if(backup.app!=='try-study'||backup.version!==1||!validateState(backup.state)||!Array.isArray(backup.files))throw Error('ไฟล์นี้ไม่ใช่ข้อมูลสำรองที่รองรับ');for(const c of backup.files){if(typeof c.id!=='string'||!c.id.startsWith('upload-')||!Array.isArray(c.pages)||!c.pages.length||c.pages.length>500||typeof c.fileBase64!=='string'||!['pdf','pptx'].includes(c.type))throw Error('ข้อมูลไฟล์สไลด์ในสำรองไม่ถูกต้อง');}if(!confirm('นำเข้าข้อมูลนี้แทนความก้าวหน้า โน้ต และผลสอบปัจจุบันหรือไม่? ควรส่งออกข้อมูลปัจจุบันก่อน'))return;for(const c of backup.files){const bytes=Uint8Array.from(atob(c.fileBase64),ch=>ch.charCodeAt(0));await putCourse({id:c.id,n:0,title:String(c.title),thai:String(c.thai||'วิชาของฉัน'),desc:'สไลด์ของคุณ',icon:'file',color:'purple',custom:true,type:c.type,pages:c.pages.map((p,i)=>({number:i+1,title:String(p.title||'สไลด์'),text:String(p.text||'')})),topics:[],questions:[],fileBlob:new Blob([bytes],{type:c.mime||'application/octet-stream'})});}const restored=fresh();for(const field of Object.keys(restored))if(backup.state[field]!==undefined)restored[field]=backup.state[field];restored.goal=[10,15,20,30,45,60].includes(restored.goal)?restored.goal:20;Object.assign(state,restored);save();const base=courses.filter(c=>!c.custom);setCourses([...base,...await storedCourses()]);closeModal();go('#home');toast('กู้คืนข้อมูลสำรองแล้ว');}catch(e){status.innerHTML=`<p class="error">${esc(e.message||'อ่านไฟล์สำรองไม่สำเร็จ')}</p>`;}}
export function openSearch(query=''){modal(modalHead('ค้นหาในบทเรียน')+`<form id="modal-search" role="search"><input id="search-query" aria-label="คำค้น" placeholder="เช่น CPI, cache, pipeline หรือชื่อบทเรียน" value="${esc(query)}" maxlength="150" style="width:100%"><button class="sr-only" type="submit">ค้นหา</button></form><div class="search-results" id="search-results"></div>`);const input=document.getElementById('search-query');const find=()=>{const q=input.value.trim().toLowerCase();const output=document.getElementById('search-results');if(q.length<2){output.innerHTML='<p class="muted" style="font-size:12px">พิมพ์อย่างน้อย 2 ตัวอักษร เพื่อค้นหาจากข้อความและคำอธิบายในสไลด์</p>';return;}const results=[];for(const c of courses){for(const p of c.pages){const text=(c.title+' '+c.thai+' '+p.title+' '+p.text).toLowerCase(),at=text.indexOf(q);if(at!==-1){const idx=p.text.toLowerCase().indexOf(q);const snippet=idx>=0?p.text.slice(Math.max(0,idx-30),idx+140):p.text.slice(0,150);results.push({c,p,snippet,rank:p.title.toLowerCase().includes(q)?0:1});}}for(const t of c.topics){if((t.title+' '+t.explain+' '+t.remember).toLowerCase().includes(q)&&!results.some(r=>r.c.id===c.id&&r.p.number===t.from))results.push({c,p:c.pages[t.from-1],snippet:t.explain.slice(0,150),rank:0});}}results.sort((a,b)=>a.rank-b.rank);output.innerHTML=results.length?`<p class="muted" style="font-size:10px;margin:0">พบ ${results.length} หน้า${results.length>30?' · แสดง 30 หน้าแรก':''}</p>`+results.slice(0,30).map(r=>`<a href="#learn/${r.c.id}/${r.p.number}" class="search-result" data-action="close-modal"><small>${esc(r.c.title)} · หน้า ${r.p.number}</small><strong>${esc(r.p.title)}</strong><p>${esc(r.snippet)}…</p></a>`).join(''):empty('ไม่พบหัวข้อที่ค้นหา','ลองใช้คำภาษาอังกฤษที่ปรากฏในสไลด์ หรือเปลี่ยนคำค้น');};input.addEventListener('input',find);document.getElementById('modal-search').addEventListener('submit',e=>{e.preventDefault();find();});find();input.focus();}
export async function handleDialogClick(b,render){switch(b.dataset.action){case'confirm-upload':await importFile();break;case'save-settings':{state.goal=Number(document.getElementById('daily-goal').value);save();closeModal();render();toast('บันทึกเป้าหมายแล้ว');break;}case'export':await exportBackup(b);break;case'import':document.getElementById('backup-input').click();break;case'reset':if(confirm('ล้างความก้าวหน้า คะแนน และโน้ตทั้งหมดหรือไม่? ควรส่งออกข้อมูลสำรองก่อน')){Object.assign(state,fresh());save();closeModal();go('#home');toast('เริ่มบันทึกใหม่แล้ว');}break;}if(b.dataset.deleteCourse){const id=b.dataset.deleteCourse,c=course(id);if(confirm('ลบ “'+c.title+'” และข้อมูลการเรียนของไฟล์นี้หรือไม่?')){await deleteCourse(id);setCourses(courses.filter(c=>c.id!==id));delete state.read[id];delete state.resume[id];for(const k of Object.keys(state.notes))if(k.startsWith(id+':'))delete state.notes[k];state.bookmarks=state.bookmarks.filter(k=>!k.startsWith(id+':'));save();openSettings();render();toast('ลบไฟล์ออกจากคลังแล้ว');}}}
